from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate the groups of nested parentheses
    groups = []
    group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        group += char

        if char == ")":
            open_braces -= 1
            if open_braces == 0:
                groups.append(group)
                group = ""

    # Step 3: Check each group for validity and balance
    def is_valid(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return not stack

    valid_groups = [group for group in groups if is_valid(group)]

    # Step 4: Return the list of separated groups
    return valid_groups

